<section>
 <div class="mb-6"><p class="text-sm font-semibold uppercase tracking-wide text-emerald-700">Seguridad y trazabilidad</p><h1 class="mt-1 text-3xl font-bold text-slate-900">Auditoría</h1><p class="mt-2 text-sm text-slate-600">Registro de operaciones críticas realizadas en el sistema (máximo 500 resultados).</p></div>
 <form method="get" action="<?= e($baseUrl) ?>/auditoria" class="mb-5 grid gap-3 rounded-xl border bg-white p-4 sm:grid-cols-2 lg:grid-cols-5"><label class="text-xs font-semibold">Buscar<input name="q" value="<?= e($filters['q']) ?>" placeholder="Usuario, entidad o ID" class="mt-1 min-h-10 w-full rounded-lg border px-3 text-sm"></label><label class="text-xs font-semibold">Acción<input name="accion" value="<?= e($filters['accion']) ?>" placeholder="crear, anular, ajustar" class="mt-1 min-h-10 w-full rounded-lg border px-3 text-sm"></label><label class="text-xs font-semibold">Desde<input type="date" name="desde" value="<?= e($filters['desde']) ?>" class="mt-1 min-h-10 w-full rounded-lg border px-3 text-sm"></label><label class="text-xs font-semibold">Hasta<input type="date" name="hasta" value="<?= e($filters['hasta']) ?>" class="mt-1 min-h-10 w-full rounded-lg border px-3 text-sm"></label><div class="flex items-end"><button class="min-h-10 rounded-lg bg-emerald-700 px-4 text-sm font-semibold text-white">Filtrar</button></div></form>
 <div class="overflow-x-auto rounded-xl border bg-white"><table class="min-w-full divide-y text-left text-sm"><thead class="bg-slate-50 text-xs uppercase"><tr><?php foreach(['Fecha','Usuario','Acción','Entidad','ID','Detalle','IP'] as $h): ?><th class="px-4 py-3"><?= e($h) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y"><?php if(!$rows): ?><tr><td colspan="7" class="px-4 py-10 text-center text-slate-500">Aún no hay operaciones registradas.</td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td class="whitespace-nowrap px-4 py-3"><?= e(date('d/m/Y H:i:s',strtotime($row['creado_en']))) ?></td><td class="px-4 py-3"><?= e($row['usuario']??'Usuario eliminado') ?></td><td class="px-4 py-3 font-semibold"><?= e($row['accion']) ?></td><td class="px-4 py-3"><?= e($row['entidad']) ?></td><td class="px-4 py-3"><?= e($row['entidad_id']??'—') ?></td><td class="max-w-sm break-words px-4 py-3"><?php $detail=$row['detalle']?json_decode((string)$row['detalle'],true):null; ?><?= e($detail?json_encode($detail,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):(string)($row['detalle']??'—')) ?></td><td class="px-4 py-3"><?= e($row['ip']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div>
